def binary_search(arr, target):
    low = 0
    high = len(arr) - 1

    while low <= high:
        mid = (low + high) // 2

        if arr[mid] == target:
            return mid
        elif target > arr[mid]:
            low = mid + 1
        else:
            high = mid - 1

    return -1

print(binary_search([1, 3, 5, 7, 9, 11, 15], 11))

def recursive_binary_search(arr, target, low, high):
    if low > high:
        return -1

    mid = (low + high) // 2

    if arr[mid] == target:
        return mid

    if target > arr[mid]:
        return recursive_binary_search(arr, target, mid + 1, high)

    return recursive_binary_search(arr, target, low, mid - 1)

arr = [1, 3, 5, 7, 9, 11, 15]
print(recursive_binary_search(arr, 7, 0, len(arr) - 1))

def contains_target(arr, target):
    low = 0
    high = len(arr) - 1

    while low <= high:
        mid = (low + high) // 2

        if arr[mid] == target:
            return True
        elif target > arr[mid]:
            low = mid + 1
        else:
            high = mid - 1

    return False

print(contains_target([2, 4, 6, 8, 10], 6))
